import java.io.File;
import javax.servlet.http.HttpServletRequest;
import java.nio.file.Paths;
import java.nio.file.Path;

public class SecureFileUploadHandler {
    public void handleSecureFileUpload(HttpServletRequest request) {
        String fileName = request.getParameter("filename");

        // Validate filename to prevent directory traversal and special characters
        if (fileName == null || !fileName.matches("[a-zA-Z0-9._-]+")) {
            throw new IllegalArgumentException("Invalid filename");
        }

        // Use Paths.get() with a fixed base directory and resolve the relative path safely
        Path basePath = Paths.get("/uploads/").toAbsolutePath().normalize();
        Path targetPath = basePath.resolve(fileName).normalize();

        // Ensure the resolved path is still within the intended base directory
        if (!targetPath.startsWith(basePath)) {
            throw new SecurityException("Access denied: path traversal detected");
        }

        File safeFile = targetPath.toFile();
        safeFile.createNewFile();
    }
}
